begin;
set local s1.tap='off';
\ir s3_fixture.sql
set local role authenticated;
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
insert into s4_data values('transfer',public.request_room_owner_transfer_v1(pg_temp.s3_room(),'10000002-0000-4000-8000-000000000002',true,pg_temp.s3_rev(),'33000000-0000-4000-8000-000000000010'));
select pg_temp.check(not (public.get_room_lifecycle_v1(pg_temp.s3_room())->>'can_transfer')::boolean,'pending request disables new-transfer permission in the server projection');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.request_room_owner_transfer_v1(pg_temp.s3_room(),'10000002-0000-4000-8000-000000000002',false,pg_temp.s3_rev(),gen_random_uuid())$q$)='S3004','one pending request per room');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.request_room_owner_transfer_v1(pg_temp.s3_room(),'10000002-0000-4000-8000-000000000002',false,pg_temp.s3_rev(),'33000000-0000-4000-8000-000000000010')$q$)='S1007','same ID changed intent is denied');
select pg_temp.as_user('10000003-0000-4000-8000-000000000003');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.respond_room_owner_transfer_v1((select (v->>'transfer_id')::uuid from s4_data where k='transfer'),true,0,gen_random_uuid())$q$)='42501','outsider cannot accept transfer');
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select pg_temp.check((public.respond_room_owner_transfer_v1((select (v->>'transfer_id')::uuid from s4_data where k='transfer'),true,pg_temp.s3_rev(),gen_random_uuid())->>'outcome')='applied','target accepts ownership and original owner leave atomically');
select pg_temp.check((public.get_room_lifecycle_v1(pg_temp.s3_room())->>'can_close')::boolean,'new owner immediately gains close authority');
reset role;
select pg_temp.check((select owner_id='10000002-0000-4000-8000-000000000002' from public.rooms where id=pg_temp.s3_room()),'only owner ID is transferred');
select pg_temp.check(not exists(select 1 from public.participants where room_id=pg_temp.s3_room() and profile_id='10000001-0000-4000-8000-000000000001'),'fixed leave_after_accept removes original owner');
select pg_temp.check((select count(*)=1 from public.messages where room_id=pg_temp.s3_room() and lifecycle_event_type='owner_transfer_accepted'),'one accepted event');
insert into public.participants(room_id,profile_id,name) values(pg_temp.s3_room(),'10000001-0000-4000-8000-000000000001','Synthetic rejoined A');
set local role authenticated;
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
insert into s4_data values('ttl_transfer',public.request_room_owner_transfer_v1(pg_temp.s3_room(),'10000001-0000-4000-8000-000000000001',false,pg_temp.s3_rev(),gen_random_uuid()));
reset role;
update private.s3_transfer_requests set expires_at=clock_timestamp()-interval '1 second' where id=(select (v->>'transfer_id')::uuid from s4_data where k='ttl_transfer');
set local role authenticated;
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
select pg_temp.check((public.respond_room_owner_transfer_v1((select (v->>'transfer_id')::uuid from s4_data where k='ttl_transfer'),true,pg_temp.s3_rev(),gen_random_uuid())->>'outcome')='expired','mutation discovers TTL as a normal committed expiry outcome');
reset role;
select pg_temp.check((select status='expired' and terminal_reason='ttl' from private.s3_transfer_requests where id=(select (v->>'transfer_id')::uuid from s4_data where k='ttl_transfer')),'mutation expiry state is retained rather than exception rollback');
rollback;
